<template>
  <div class="admin-page" v-if="true">
    <Header :title="titulo" :hideToggle="false"/>
    <Menu />
      <div id="home-content">
        <PageTitle icon="fa fa-home" main="Home" sub="Administração do Sistema"/>
        <div class="stats">
          <Statistics title="Orientadores" :value="valueOrientadores" icon="fa fa-bookmark" color="#212C40"/>
          <Statistics title="Projetos" :value="valueProjetos" icon="fa fa-book" color="#EBC573" />
          <Statistics title="Cursos" :value="valueCursos" icon="fa fa-folder" color="#8BCCB3" />
          <Statistics title="Usuários" :value="valueUsuarios" icon="fa fa-user" color="#999485" />
        </div>
      </div>
    <Footer />
  </div>
</template>

<script>
import { baseUrl, baseTitulo } from '../../../config/global'
import { mapState } from 'vuex'
import axios from 'axios'
import PageTitle from '../templates/PageTitle'
import Statistics from '../templates/Statistics'
import Header from '../templates/Header'
import Menu from '../templates/Menu'
import Footer from '../templates/Footer'

export default {
    name: 'Index',
    components: { PageTitle, Statistics, Header, Menu, Footer },
    computed: mapState(['login']),
    data: function(){
      return{
        validacao: null,
        valueOrientadores: '',
        valueProjetos: '',
        valueUsuarios: '',
        valueCursos: '',
        valueAdm: '',
        titulo: baseTitulo
      }
    },
    methods: {
      GetStats(){
        axios.get(baseUrl + 'cursos/count')
          .then(res => this.valueCursos = res.data.count)
          // .catch(this.Fracasso('Erro ao capturar quantidade de Cursos'))
        axios.get(baseUrl + 'usuarios/count')
          .then(res => this.valueUsuarios = res.data.count)
          // .catch(this.Fracasso('Erro ao capturar quantidade de Usuários'))
        axios.get(baseUrl + 'projetos/count')
          .then(res => this.valueProjetos = res.data.count)
          // .catch(this.Fracasso('Erro ao capturar quantidade de Projetos'))
        axios.get(baseUrl + 'orientadores/count')
          .then(res => this.valueOrientadores = res.data.count)
          // .catch(this.Fracasso('Erro ao capturar quantidade de Orientadores'))
      },
      VerificarLogin(){
        axios.get(baseUrl + 'usuarios/logged')
          .then(resp => this.validacao = resp.data)
          .catch()
      },
      Redirecionar(){
        if(this.validacao != true){
          //this.$router.push('/erro')
        }
      },
      Fracasso(mensagem){
        this.$toasted.show(mensagem, { 
          type: "error", 
          icon: 'times',
          position: "top-right", 
          duration : 5000
        })
      }
    },
    mounted(){
      document.title = "BTA - Home"
      this.VerificarLogin()
      this.GetStats()
      this.Redirecionar()
    }
}
</script>

<style>
  #home-content{
    grid-area: contentAdmin;
    background-color: #efefef;
    padding: 20px;
  }

  .stats{
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
  }
</style>