<template>
  <div class="admin-page" v-if="login">
    <Header :title="titulo" :hideToggle="false"/>
    <Menu />
    <div id="cursoList-content">
      <PageTitle icon="fa fa-home" main="Curso" sub="Listagem"/>
      <b-table 
        class="table-rank"
        striped hover 
        :items="cursosLista" 
        :fields="fields"
        :sort-by.sync="sortBy"
        :sort-desc.sync="sortDesc"
        :per-page="perPage"
        :current-page="currentPage"
      >
        <template slot="actions" slot-scope="row">
          <b-button variante="primary" class="mr-2" @click="Modal(row.item.codCurso, row.item.ativo, row.item.descricaoCurso)">
            <i class="fa fa-eye-slash" v-if="row.item.ativo == '1'"></i>
            <i class="fa fa-eye" v-if="row.item.ativo == '0'"></i>
          </b-button>
        </template> 
      </b-table>
      <b-pagination
        v-model="currentPage"
        :total-rows="this.cursosLista.length"
        :per-page="perPage"
      ></b-pagination>

    <div v-if="showModalEdit">
      <transition name="modal">
        <div class="modal-mask">
          <div class="modal-wrapper">
            <div class="modal-dialog" role="document">
              <div class="modal-content">
                <div class="modal-header">
                  <h5 class="modal-title">{{acao}}</h5>
                  <button type="button" class="close" data-dismiss="modal" aria-label="Close">
                    <span aria-hidden="true" @click="showModalEdit = false">&times;</span>
                  </button>
                </div>
                <div class="modal-body">
                  <p>Deseja {{mensagem}} o curso {{ cursoEscolhidoNome }} ?</p>
                </div>
                <div class="modal-footer">
                  <button type="button" class="btn btn-primary" @click="showModalEdit = false">Cancelar</button>
                  <button type="button" class="btn btn-danger" @click="MudarAtivo()">{{acao}}</button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </transition>
    </div>

    </div>
    <Footer />
  </div>
</template>

<script>
import { baseUrl, baseTitulo } from '../../../config/global'
import { mapState } from 'vuex'
import axios from 'axios'
import PageTitle from '../templates/PageTitle'
import Header from '../templates/Header'
import Menu from '../templates/Menu'
import Footer from '../templates/Footer'

export default {
    name: 'UsuarioList',
    components: { PageTitle, Header, Menu, Footer },
    computed: mapState(['login']),
    data: function(){
      return{
        sortBy: 'likes',
        sortDesc: true,
        perPage: 5,
        currentPage: 1,
        showModalEdit: false,
        cursoEscolhidoNome: '',
        cursoEscolhidoId: '',
        cursosLista: [],
        fields: [
          {key: 'codCurso', label: 'Código', sortable: false},
          {key: 'abreviacao', label: 'Abreviação', sortable: true},
          {key: 'descricaoCurso', label: 'Nome', sortable: false},
          {key: 'ativo', label: 'Ativo', sortable: true, formatter: value => value == 1 ? 'Sim' : 'Não'},
          {key: 'actions', label: 'Ações'}
        ],
        titulo: baseTitulo,
        acao: '',
        mensagem: ''
      }
    },
    mounted(){
      this.CarregarCursos()
      document.title = "BTA - Lista de Cursos"
      this.Redirecionar()
    },
    methods: {
      CarregarCursos(){
        axios.get(baseUrl + "cursos/buscar/inativos")
          .then(response => (this.cursosLista = response.data.data))
      },
      MudarAtivo(){
        axios.post(baseUrl + 'cursos/' + this.acao.toLowerCase() + '/' + this.cursoEscolhidoId)
          .then((response) => {
            if(response.data.status == 'negado'){
              this.Fracasso()
              return
            }
            this.Sucesso(this.mensagem)
            this.CarregarCursos()
          })
          .catch(function(erro){
            this.Fracasso(erro)
          })
          this.showModalEdit = false
      },
      Modal(idCurso, status, nomeCurso){
        if(status == '1'){
          this.acao = 'Desativar'
          this.mensagem = "desativar"
        }
        else{
          this.acao = 'Ativar'
          this.mensagem = "ativar"
        }
        this.cursoEscolhidoNome = nomeCurso
        this.cursoEscolhidoId = idCurso
        this.showModalEdit = true
      },
      Redirecionar(){
        if(this.login != true){
          this.$router.push('/erro')
        }
      },
      Fracasso(){
        this.$toasted.show("Erro ao Listar Cursos", { 
          type: "error", 
          icon: 'times',
          position: "top-right", 
          duration : 5000
        })
      },
      Sucesso(mensagem){
        let status
        if(mensagem == 'desativar'){
          status = 'desativado'
        }
        else{
          status = 'ativado'
        }
        this.$toasted.show("Curso " + status + " com Sucesso!!", { 
          type: "success", 
          icon: 'check',
          position: "top-right", 
          duration : 5000
        })
      }
    }
}
</script>

<style>
  #cursoList-content{
    grid-area: contentAdmin;
    background-color: #efefef;
    padding: 20px;
  }
</style>