<script>

export default {
  name: 'app',
  data(){
    return{
      windowHeight: 0,
      mobile: false
    }
  },

  mounted() {
    this.$nextTick(function() {
      window.addEventListener('resize', this.getWindowHeight)

      //Init
      this.getWindowHeight()
    })

  },

  methods: {
    getWindowHeight() {
      this.windowHeight = document.documentElement.clientHeight;
    },
    Sucesso(mensagem, tempo = 5000){
      this.$toasted.show(mensagem, { 
        type: "success", 
        icon: 'check',
        position: "top-right", 
        duration : tempo
      })
    },
    Fracasso(mensagem, tempo = 5000){
      this.$toasted.show(mensagem, { 
        type: "error", 
        icon: 'times',
        position: "top-right", 
        duration : tempo
      })
    }
  },
  beforeDestroy() {
    window.removeEventListener('resize', this.getWindowHeight);
  },
}
</script>

