<template>
    <div class="page">
        <Header />
        <article class="container main margin-main">
            <h2 class="tituloPagina">Busca Avançada</h2>
            
            <b-row>
                <b-col md="9" sm="12">
                    <div class="active-pink-4 mb-4">
                        <b-form-input v-model="pesquisa" placeholder="Buscar..." class="linha-busca"></b-form-input>
                    </div>
                </b-col>
                <b-col md="3" sm="12">
                    <b-dropdown :text="filtroDropdown === '' ? valorPadrao : filtroDropdown" variant="danger" class="linha-busca dropdown-pesquisa drop">
                        <b-dropdown-item class="drop" @click="TrocaFiltro('Título', 'titulo')">Título</b-dropdown-item>
                        <b-dropdown-item class="drop" @click="TrocaFiltro('Curso', 'curso')">Curso</b-dropdown-item>
                        <b-dropdown-item class="drop" @click="TrocaFiltro('Autor', 'autor')">Autor</b-dropdown-item>
                        <b-dropdown-item class="drop" @click="TrocaFiltro('Orientador', 'orientador')">Orientador</b-dropdown-item>
                        <b-dropdown-item class="drop" @click="TrocaFiltro('Palavras-Chave', 'palavrasChave')">Palavras-Chave</b-dropdown-item>
                    </b-dropdown>
                </b-col>
            </b-row>

            
            <div class="botaoCentro mb-5 mt-3">
                <b-button variant="outline-danger" @click="Pesquisa()">Pesquisar</b-button>
            </div>

            <div v-if="pesquisaBool">
                <b-table 
                    class="table-rank"
                    striped hover responsive
                    :items="projetos" 
                    :fields="fields"
                    :sort-by.sync="sortBy"
                    :sort-desc.sync="sortDesc"
                    :per-page="perPage"
                    :current-page="currentPage"
                >
                    <template slot="action" slot-scope="trabalho">
                        <router-link :to="'/projeto?id=' + trabalho.item.codProjeto">
                            <a>
                                <button class="outline black">
                                    <i class="fa fa-search"></i>
                                </button>
                            </a>
                        </router-link>
                    </template>
                    <template slot="autores" slot-scope="aluno">
                        {{ aluno.item.autores|formatarAlunos }}
                    </template>
                    <template slot="dataAvaliacao" slot-scope="dataAvaliacao">
                        {{ dataAvaliacao.item.dataAvaliacao|formatarAno }}
                    </template>
                    <template slot="download" slot-scope="downloadItem">
                        <a :href="url + 'projetos/download_file/' + downloadItem.item.nomeArquivo" download="">
                            <button class="outline black">
                                <i class="fa fa-download"></i>
                            </button>
                        </a>
                    </template>
                </b-table>
                <b-pagination
                    v-model="currentPage"
                    :total-rows="this.projetos.length"
                    :per-page="perPage"
                    class="mt-3"
                ></b-pagination>
            </div>
        </article>
        <Footer />
    </div>
</template>

<script>
import { baseUrl } from '../../../config/global'
import Header from '../templates/Header'
import Footer from '../templates/Footer'
import axios from 'axios'

export default {
    name: 'busca',
    components: { Header, Footer },
    data: function(){
        return{
            url: baseUrl,
            sortBy: 'likes',
            sortDesc: true,
            perPage: 20,
            currentPage: 1,
            projetos: [],
            fields: [
                {key: 'action', label: 'Visualizar', sortable: true},
                {key: 'tituloProjeto', label: 'Título', sortable: true},
                {key: 'curso.abreviacao', label: 'Curso', sortable: true},
                {key: 'autores', label: 'Autores', sortable: false},
                {key: 'orientadores', label: 'Orientador', sortable: true, formatter: value => value == null ? 'Sem Orientador' : value.nomeOrientador},
                {key: 'dataAvaliacao', label: 'Ano', sortable: true},
                {key: 'download', label: 'Download'}
            ],
            pesquisa: '',
            filtro: 'titulo',
            filtroDropdown: '',
            valorPadrao: 'Tipo de Pesquisa',
            pesquisaBool: false
        }
    },
    methods: {
        Pesquisa(){
            this.Carregando()
            axios.get(baseUrl + "projetos/buscar/" + this.filtro, {
                params: {
                    ['query']: this.pesquisa,
                    ['ordem']: '0',
                    ['crescente']: '1'
                }
            })
                .then(response => {
                    if(response.data.cod_s != '1'){
                        this.Fracasso()
                        return
                    }
                    this.projetos = response.data.data
                    this.pesquisaBool = true
                })
                .catch((erro) => {
                    this.pesquisaBool = false
                })
        },
        PesquisaInicial(){
            if(!this.$route.query.busca)
                return
            this.Carregando()
            axios.get(baseUrl + "projetos/buscar/" + this.filtro, {
                params: {
                    ['query']: this.$route.query.busca,
                    ['ordem']: '0',
                    ['crescente']: '1'
                }
            })
                .then(response => {
                    if(response.data.cod_s != '1'){
                        this.Fracasso()
                        return
                    }
                    this.pesquisa = this.$route.query.busca
                    this.projetos = response.data.data
                    this.pesquisaBool = true
                })
                .catch((erro) => {
                    this.pesquisaBool = false
                })
        },
        TrocaFiltro(filterDrop, filter){
            this.filtro = filter
            this.filtroDropdown = filterDrop
        },
        Sucesso(){
            this.$toasted.show("Logado com Sucesso!!", { 
            type: "success", 
            icon: 'check',
            position: "top-right", 
            duration : 5000
            })
        },
        Fracasso(){
            this.$toasted.show("Pesquisa não encontrada", { 
            type: "error", 
            icon: 'times',
            position: "top-right", 
            duration : 5000
            })
        },
        Carregando(){
            this.$toasted.show("Carregando", { 
            type: "toasted-primary", 
            icon: 'hourglass-start',
            position: "top-right", 
            duration : 2000
            })
        }
    },
    mounted(){
        this.PesquisaInicial()
        document.title = "BTA - Buscar"
    },
    filters: {
        formatarAlunos: alunos => {
            if(alunos[1] == null || alunos[1] == undefined)
              return alunos[0].nomeAutor
            if(alunos[2] == null || alunos[2] == undefined)
              return alunos[0].nomeAutor + ', ' + alunos[1].nomeAutor
            if(alunos[3] == null || alunos[3] == undefined)
              return alunos[0].nomeAutor + ', ' + alunos[1].nomeAutor + ', ' + alunos[2].nomeAutor
            if(alunos[4] == null || alunos[4] == undefined)
              return alunos[0].nomeAutor + ', ' + alunos[1].nomeAutor + ', ' + alunos[2].nomeAutor + ', ' + alunos[3].nomeAutor
            if(alunos[5] == null || alunos[5] == undefined)
              return alunos[0].nomeAutor + ', ' + alunos[1].nomeAutor + ', ' + alunos[2].nomeAutor + ', ' + alunos[3].nomeAutor + ', ' + alunos[4].nomeAutor
        },
        formatarAno: ano =>{
          return ano.substr(12, 4);
        }
    }
}
</script>

<style>
.drop{
    z-index: 99;
}

.dropdown-pesquisa{
    width: 75%;
    right: auto;
    left: 50%;
    -webkit-transform: translate(-50%, 0);
    -o-transform: translate(-50%, 0);
    transform: translate(-50%, 0);
}

.linha-busca{
    height: 40px;
}

.table th, .table td {
    vertical-align: unset ;
}
</style>