<template>
  <div class="admin-page" v-if="true">
    <Header :title="titulo" :hideToggle="false"/>
    <Menu />
    <div id="cursoAdd-content">
      <PageTitle icon="fa fa-home" main="Curso" sub="Cadastro"/>
      <b-form>
        <b-row>
          <b-col md="6" sm="12">
              <b-form-group label="Nome do Curso:" label-for="curso-name">
                  <b-form-input id="curso-nome" type="text" v-model="curso.nome" placeholder="Digite o Nome do Curso" required>
                  </b-form-input>
              </b-form-group>
          </b-col>
          <b-col md="6" sm="12">
              <b-form-group label="Sigla do Curso:" label-for="curso-sigla">
                <b-form-input
                  id="input-live"
                  v-model="curso.sigla"
                  :state="SiglaState"
                  aria-describedby="input-live-help input-live-feedback"
                  placeholder="Digite a Sigla do Curso"
                  maxlength="3"
                  trim
                ></b-form-input>
                <b-form-invalid-feedback id="input-live-feedback">
                  Coloque a sigla do curso em maiusculo e no máximo com 3 caracteres.
                </b-form-invalid-feedback>
              </b-form-group>
          </b-col>
        </b-row>
        <b-button variant="primary" @click='save'>
          Salvar
        </b-button>
        <b-button class="ml-2" @click='reset'>
          Cancelar
        </b-button>
      </b-form>
    </div>
    <Footer />
  </div>
</template>

<script>
import { baseUrl, baseTitulo } from '../../../config/global'
import axios from 'axios'
import PageTitle from '../templates/PageTitle'
import Header from '../templates/Header'
import Menu from '../templates/Menu'
import Footer from '../templates/Footer'

export default {
    name: 'UsuarioList',
    components: { PageTitle, Header, Menu, Footer },
    computed: {
      SiglaState() {
        return this.curso.sigla.length > 1 ? true : false
      }
    },
    data: function(){
      return{
        curso:{
          nome: '',
          sigla: ''
        },
        titulo: baseTitulo
      }
    },
    methods:{
      reset(){
        this.curso = {}
      },
      save(){
        let d = new FormData()
        d.append('nomeCurso', this.curso.nome)
        d.append('abreviacao', this.curso.sigla)
        axios.post(baseUrl + 'cursos/cadastrar', d)
          .then((response) => {
            if(response.data.status == 'negado'){
              this.Fracasso()
              return
            }
            this.Sucesso()
            this.$router.push('/admin/curso')
          })
          .catch(function(erro){
            this.Fracasso(erro)
          })
      },
      // Redirecionar(){
      //   if(this.login != true){
      //     this.$router.push('/erro')
      //   }
      // },
      Sucesso(){
        this.$toasted.show("Curso Adicionado com Sucesso!!", { 
          type: "success", 
          icon: 'check',
          position: "top-right", 
          duration : 5000
        })
      },
      Fracasso(erro = "Erro ao Adicionar Curso"){
        this.$toasted.show(erro, { 
          type: "error", 
          icon: 'times',
          position: "top-right", 
          duration : 5000
        })
      }
    },
    mounted(){
      document.title = "BTA - Adicionar Curso"
      this.Redirecionar()
    }
}
</script>

<style>
  #cursoAdd-content{
    grid-area: contentAdmin;
    background-color: #efefef;
    padding: 20px;
  }
</style>