<template>
  <div class="loginPage">
    <div class="center">
      <div class="form">
        <h3 class="loginTitulo">Login BTA</h3>
        <b-form>
          <b-form-group
            id="input-group-1"
            label="Login:"
            label-for="input-1"
          >
            <b-form-input
              id="input-1"
              v-model="username"
              type="text"
              required
              placeholder="Login"
            ></b-form-input>
          </b-form-group>

          <b-form-group id="input-group-2" label="Senha:" label-for="input-2">
            <b-form-input
              id="input-2"
              v-model="password"
              type="password"
              required
              placeholder="Senha"
            ></b-form-input>
          </b-form-group>
          <div class="botaoCentro mt-4">
            <b-button @click="Voltar()">Cancelar</b-button>
            <b-button @click="Login()" variant="primary" class="ml-2">Login</b-button>
          </div>
          <p class="mt-10">Coryright © {{ new Date().getFullYear() }}</p>
        </b-form>
      </div>
    </div>
  </div>
</template>

<script>
import { baseUrl } from '../../../config/global'
import { mapState } from 'vuex'
import axios from 'axios'

export default {
    name: 'UsuarioList',
    computed: mapState(['login']),
    data() {
      return {
        username: '',
        password: ''
      }
    },
    methods: {
      Login(){
        this.Carregando()
        let d = new FormData()
        d.append('username', this.username)
        d.append('password', this.password)
        axios.post(baseUrl + 'usuarios/login', d)
          .then((response) => {
            if(response.data.status == 'erro'){
              this.Fracasso()
              return
            }
            this.$store.commit('postLogin')
            this.Sucesso()
            this.$router.push('/admin')
          })
          .catch(function(){
            this.Fracasso()
          })
      },
      Sucesso(){
        this.$toasted.show("Logado com Sucesso!!", { 
          type: "success", 
          icon: 'check',
          position: "top-right", 
          duration : 5000
        })
      },
      Fracasso(){
        this.$toasted.show("Login ou Senha Incorreto!!", { 
          type: "error", 
          icon: 'times',
          position: "top-right", 
          duration : 5000
        })
      },
      Carregando(){
        this.$toasted.show("Carregando", { 
          type: "toasted-primary", 
          icon: 'hourglass-start',
          position: "top-right", 
          duration : 2000
        })
      },
      Voltar(){
        this.$router.push('/')
      }
    }
  }
</script>

<style>
.loginPage{
  background-color: rgba(0, 0, 0, 0.7);
  height: 100vh;
}

.center {
  background-color: white;
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  -ms-transform: translate(-50%, -50%); /* for IE 9 */
  -webkit-transform: translate(-50%, -50%); /* for Safari */

  /* optional size in px or %: */
  width: 30%;
  height: 500px;
  border-radius: 5px;
  padding: 10px;
}

.form{
  width: 85%;
  margin: 0 auto;
  padding-top: 20px;
}

.loginTitulo{
  padding-bottom: 50px;
  text-align: center;
}

.mt-10{
  padding-top: 120px;
  text-align: center;
}

@media screen and (max-width: 992px) {
  .center {
    width: 60%;
  }
}

@media screen and (max-width: 600px) {
  .center {
    width: 95%;
  }
}

</style>