<template>
  <div class="admin-page" v-if="true">
    <Header :title="titulo" :hideToggle="false"/>
    <Menu />
    <div id="usuarioList-content">
      <PageTitle icon="fa fa-home" main="Usuário" sub="Listagem"/>
      <b-table 
        class="table-rank"
        striped hover 
        :items="usuarios" 
        :fields="fields"
        :sort-by.sync="sortBy"
        :sort-desc.sync="sortDesc"
        :per-page="perPage"
        :current-page="currentPage"
      >
        <template slot="actions" slot-scope="row">
          <b-button variante="primary" class="mr-2" @click="Editar(row.item.codUsuario, row.item.nomeUsuario)">
            <i class="fa fa-pencil"></i>
          </b-button>
          <b-button v-b-modal.modal-center @click="Modal(row.item)">
            <i class="fa fa-trash"></i>
          </b-button>
        </template> 
      </b-table>
      <b-pagination
        v-model="currentPage"
        :total-rows="this.usuarios.length"
        :per-page="perPage"
        aria-controls="listagemCursos"
      ></b-pagination>
    </div>
    <Footer />

    <div v-if="showModalEdit">
        <transition name="modal">
          <div class="modal-mask">
            <div class="modal-wrapper">
              <div class="modal-dialog" role="document">
                <div class="modal-content">
                  <div class="modal-header">
                    <h5 class="modal-title">Excluir</h5>
                    <button type="button" class="close" data-dismiss="modal" aria-label="Close">
                      <span aria-hidden="true" @click="showModalEdit = false">&times;</span>
                    </button>
                  </div>
                  <div class="modal-body">
                    <p>Deseja excluir o Usuário {{ usuarioEscolhidoNome }}?</p>
                  </div>
                  <div class="modal-footer">
                    <button type="button" class="btn btn-primary" @click="showModalEdit = false">Cancelar</button>
                    <button type="button" class="btn btn-danger" @click="Excluir" >Excluir</button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </transition>
      </div>

  </div>
</template>

<script>
import { baseUrl, baseTitulo } from '../../../config/global'
import axios from 'axios'
import PageTitle from '../templates/PageTitle'
import Header from '../templates/Header'
import Menu from '../templates/Menu'
import Footer from '../templates/Footer'

export default {
    name: 'UsuarioList',
    components: { PageTitle, Header, Menu, Footer },
    computed: {

    },
    data: function(){
      return{
        sortBy: 'likes',
        sortDesc: true,
        perPage: 5,
        currentPage: 1,
        showModalEdit: false,
        usuarioEscolhidoNome: '',
        usuarioEscolhidoId: '',
        usuarios: null,
        fields: [
          {key: 'codUsuario', label: 'Código', sortable: false},
          {key: 'nomeUsuario', label: 'Nome', sortable: true},
          {key: 'tipoUsuario', label: 'Administrador', sortable: true, formatter: function(value){
            if(value == 1)
              return 'Secretaria'
            else if(value == 2)
              return 'Coordenação'
            else
              return 'Admin'
          }},
          {key: 'actions', label: 'Ações'}
        ],
        titulo: baseTitulo
      }
    },
    mounted(){
      axios.get(baseUrl + 'usuarios/buscar')
        .then(response => {
          this.usuarios = response.data.data
          if(response.data.cod_s == 0){
            this.Fracasso(response.data.status)
            return
          }
        })
        // .catch(this.Fracasso('Erro ao Listar Usuário'))

      document.title = "BTA - Lista de Usuários",
      this.Redirecionar()
    },
    methods: {
      Excluir(){
        axios.post(baseUrl + 'usuarios/delete/' + this.usuarioEscolhidoId)
          .then((response) => {
            if(response.data.status == 'negado'){
              this.Fracasso()
              return
            }
            this.showModalEdit = false
            this.Sucesso()
            this.$router.push('/admin/usuario')
          })
          .catch(function(erro){
            this.Fracasso(erro)
            this.showModalEdit = false
          })
      },
      Editar(idUsuario){
        this.$router.push('/admin/usuario/editar?id=' + idUsuario) // -> /user/123
      },
      Modal(item){
        this.usuarioEscolhidoId = item.codUsuario
        this.usuarioEscolhidoNome = item.nomeUsuario
        this.showModalEdit = true
      },
      Redirecionar(){
        // if(this.login != true){
        //   this.$router.push('/erro')
        // }
      },
      Sucesso(){
        this.$toasted.show("Usuário Adicionado com Sucesso!!", { 
          type: "success", 
          icon: 'check',
          position: "top-right", 
          duration : 5000
        })
      },
      Fracasso(mensagem){
        this.$toasted.show(mensagem, { 
          type: "error", 
          icon: 'times',
          position: "top-right", 
          duration : 5000
        })
      }
    }
}
</script>

<style>
  #usuarioList-content{
    grid-area: contentAdmin;
    background-color: #efefef;
    padding: 20px;
  }
</style>