<template>
    <div class="page">
        <!-- HEADER -->
        <Header />

        <main class="container main">
            <h2 class="titulo margin-top">{{projeto.tituloProjeto}}</h2>
            <h5 class="titulo mb-5">{{projeto.subTitulo}}</h5>

            <b-row>
              <b-col md="8" sm="12">
                <b-row>
                  <b-col>
                    <p>Data de Avaliação:</p>
                  </b-col>
                  <b-col>
                    Autores:
                  </b-col>
                </b-row>
                <b-row>
                  <b-col>
                    <p>{{projeto.dataAvaliacao}}</p>
                  </b-col>
                  <b-col>
                    <p>{{projeto.autores}}</p>
                  </b-col>
                </b-row>
                <b-row>
                  <b-col>
                    <p>Curso:</p>
                  </b-col>
                  <b-col>
                    <p>Orientador:</p>
                  </b-col>
                </b-row>
                <b-row>
                  <b-col>
                    <p>{{projeto.curso.descricaoCurso}}</p>
                  </b-col>
                  <b-col>
                    <p>{{projeto.orientadores.nomeOrientador}}</p>
                  </b-col>
                </b-row>
                <b-row>
                  <b-col>
                    <p>Palavras-Chave: {{projeto.palavrasChave}}</p>
                  </b-col>
                </b-row>
              </b-col>
              
              <b-col md="4" sm="12">
                <div class="info box">
                  <b-row>
                    <b-col>
                      <p class="p-card">Visualizações: {{projeto.numVisitas}}</p>
                    </b-col>
                  </b-row>
                  <b-row>
                    <b-col>
                      <p class="p-card">Likes: {{projeto.likes}}</p>
                    </b-col>
                    <b-col>
                      <p>Deslikes: {{projeto.deslikes}}</p>
                    </b-col>
                  </b-row>
                  <b-row>
                  </b-row>
                  <b-row>
                    <b-col>
                      <p class="p-card">Downloads: {{projeto.numDownloads}}</p>
                    </b-col>
                  </b-row>
                </div>
              </b-col>
            </b-row>

            <b-row>
              <b-col md="12" sm="12">
                Resumo
              </b-col>
              <b-col md="12" sm="12">
                {{projeto.descricao}}
              </b-col>
            </b-row>
                    <div id="grupoBotaoBusca">
                        <a class="botoesBusca" :href="url + 'projetos/download_file/' + projeto.nomeArquivo" :download="projeto.tituloProjeto">
                            <b-button>Download</b-button>
                        </a>
                        <a class="botoesBusca" :href="url + 'projetos/download_file/' + projeto.nomeArquivo" :download="projeto.tituloProjeto">
                            <b-button>Visualizar PDF</b-button>
                        </a>
                    </div>

        </main>

        <!-- FOOTER -->
        <Footer />
    </div>
</template>

<script>
import $ from 'jquery'
import { baseUrl } from '../../../config/global'
import axios from 'axios'
import Header from '../templates/Header'
import Footer from '../templates/Footer'

export default {
    name: 'homePage',
    components: { Header, Footer },
    data: function(){
      return{
        projeto: {},
        url: baseUrl
      }
    },
    methods:{
      getProjeto(){
        axios
        .get(baseUrl + 'projetos/get/' + this.$route.query.id)
            .then(response => {
              this.projeto = response.data.data
              document.title = "BTA - " + this.projeto.tituloProjeto
            })
      }
    },
    mounted(){
      this.getProjeto()
    }
}
</script>

<style>
.titulo{
    text-align: center;
}

.box {
  width: 100%;
  height: 100%;
  margin: 0 auto;
  padding-top: 10px;
  font-weight: bold;
}

.info {
  box-shadow: 0px 0px 14px 0px rgba(0,0,0,0.4);
}

.p-card{
  margin-left: 10px;
}

.margin-top{
  margin-top: 65px;
}
</style>