<template>
  <div class="admin-page" v-if="login">
    <Header :title="titulo" :hideToggle="false"/>
    <Menu />
    <div id="orientadorList-content">
      <PageTitle icon="fa fa-home" main="Orientadores" sub="Listagem"/>
      <b-table 
        class="table-rank"
        striped hover 
        :items="orientador" 
        :fields="fields"
        :sort-by.sync="sortBy"
        :sort-desc.sync="sortDesc"
        :per-page="perPage"
        :current-page="currentPage"
      >
        <template slot="actions" slot-scope="row">
          <b-button variante="primary" class="mr-2" @click="Editar(row.item.codOrientador)">
            <i class="fa fa-pencil"></i>
          </b-button>
          <b-button v-b-modal.modal-center @click="modal(row.item)">
            <i class="fa fa-trash"></i>
          </b-button>
        </template> 
      </b-table>
      <b-pagination
        v-model="currentPage"
        :total-rows="this.orientador.length"
        :per-page="perPage"
        aria-controls="listagemCursos"
      ></b-pagination>
    </div>
    <Footer />

    <div v-if="showModalEdit">
      <transition name="modal">
        <div class="modal-mask">
          <div class="modal-wrapper">
            <div class="modal-dialog" role="document">
              <div class="modal-content">
                <div class="modal-header">
                  <h5 class="modal-title">Excluir</h5>
                  <button type="button" class="close" data-dismiss="modal" aria-label="Close">
                    <span aria-hidden="true" @click="showModalEdit = false">&times;</span>
                  </button>
                </div>
                <div class="modal-body">
                  <p>Deseja excluir o orientador {{ orientadorEscolhido }}?</p>
                </div>
                <div class="modal-footer">
                  <button type="button" class="btn btn-primary" @click="showModalEdit = false">Cancelar</button>
                  <button type="button" class="btn btn-danger" @click="excluir" >Excluir</button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </transition>
    </div>

  </div>
</template>

<script>
import { baseUrl, baseTitulo } from '../../../config/global'
import { mapState } from 'vuex'
import axios from 'axios'
import PageTitle from '../templates/PageTitle'
import Header from '../templates/Header'
import Menu from '../templates/Menu'
import Footer from '../templates/Footer'

export default {
    name: 'UsuarioList',
    components: { PageTitle, Header, Menu, Footer },
    computed: mapState(['login']),
    data: function(){
      return{
        sortBy: 'likes',
        sortDesc: true,
        perPage: 5,
        currentPage: 1,
        showModalEdit: false,
        orientadorEscolhido: '',
        orientador: [],
        fields: [
          {key: 'codOrientador', label: 'Código', sortable: false},
          {key: 'nomeOrientador', label: 'Nome', sortable: true},
          {key: 'raOrientador', label: 'Ra Orientador', sortable: false},
          {key: 'actions', label: 'Ações'}
        ],
        titulo: baseTitulo
      }
    },
    mounted(){
      axios.get(baseUrl + 'orientadores/buscar')
        .then(response => (this.orientador = response.data.data))
        .catch()

      document.title = "BTA - Lista de Orientadores",
      this.Redirecionar()
    },
    methods: {
      Editar(idOrientador){
        this.$router.push('/admin/orientador/editar?id=' + idOrientador) // -> /user/123
      },
      excluir(){
        this.Fracasso('Excluido com sucesso')
        this.showModalEdit = false
      },
      modal(item){
        this.orientadorEscolhido = item.nomeOrientador
        this.showModalEdit = true
      },
      Redirecionar(){
        if(this.login != true){
          this.$router.push('/erro')
        }
      },
      Sucesso(){
        this.$toasted.show("Orientador Adicionado com Sucesso!!", { 
          type: "success", 
          icon: 'check',
          position: "top-right", 
          duration : 5000
        })
      },
      Fracasso(mensagem){
        this.$toasted.show(mensagem, { 
          type: "error", 
          icon: 'times',
          position: "top-right", 
          duration : 5000
        })
      }
    }
}
</script>

<style>
  #orientadorList-content{
    grid-area: contentAdmin;
    background-color: #efefef;
    padding: 20px;
  }
</style>