<template>
  <div class="admin-page" v-if="login">
    <Header :title="titulo" :hideToggle="false"/>
    <Menu />
    <div id="projetoList-content">
      <PageTitle icon="fa fa-home" main="Projeto" sub="Listagem"/>
      <b-table 
        class="table-rank"
        striped hover responsive
        :items="projetos" 
        :fields="fields"
        :sort-by.sync="sortBy"
        :sort-desc.sync="sortDesc"
        :per-page="perPage"
        :current-page="currentPage"
      >
        <template slot="tituloProjeto" slot-scope="titulo">
          <a href="#" target="_blank"> {{ titulo.item.tituloProjeto }} </a>
        </template>
        <template slot="autores" slot-scope="aluno">
          {{ aluno.item.autores|formatarAlunos }}
        </template>
        <template slot="dataAvaliacao" slot-scope="dataAvaliacao">
          {{ dataAvaliacao.item.dataAvaliacao|formatarAno }}
        </template>
        <template slot="download">
          <b-button variante="primary" class="ml-2">
            <a class="download" href="#" download="projeto"><i class="fa fa-download"></i></a>
          </b-button>
        </template>
        <template slot="actions" slot-scope="row">
          <b-button variante="primary" class="mr-2">
            <i class="fa fa-pencil"></i>
          </b-button>
          <b-button v-b-modal.modal-center @click="modal(row.item)">
            <i class="fa fa-trash"></i>
          </b-button>
        </template> 
      </b-table>
      <b-pagination
        v-model="currentPage"
        :total-rows="this.projetos.length"
        :per-page="perPage"
        aria-controls="rankingCompleto"
        class="mt-3"
      ></b-pagination>

    </div>
    <Footer />

    <div v-if="showModalEdit">
        <transition name="modal">
          <div class="modal-mask">
            <div class="modal-wrapper">
              <div class="modal-dialog" role="document">
                <div class="modal-content">
                  <div class="modal-header">
                    <h5 class="modal-title">Excluir</h5>
                    <button type="button" class="close" data-dismiss="modal" aria-label="Close">
                      <span aria-hidden="true" @click="showModalEdit = false">&times;</span>
                    </button>
                  </div>
                  <div class="modal-body">
                    <p>Deseja excluir o Projeto {{ projetoEscolhido }}?</p>
                  </div>
                  <div class="modal-footer">
                    <button type="button" class="btn btn-primary" @click="showModalEdit = false">Cancelar</button>
                    <button type="button" class="btn btn-danger" @click="excluir" >Excluir</button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </transition>
      </div>
  </div>
</template>

<script>
import { baseUrl, baseTitulo } from '../../../config/global'
import { mapState } from 'vuex'
import axios from 'axios'
import PageTitle from '../templates/PageTitle'
import Header from '../templates/Header'
import Menu from '../templates/Menu'
import Footer from '../templates/Footer'

export default {
    name: 'ProjetosList',
    components: { PageTitle, Header, Menu, Footer },
    computed: mapState(['login']),
    data: function(){
      return{
        sortBy: 'likes',
        sortDesc: true,
        perPage: 5,
        currentPage: 1,
        showModalEdit: false,
        projetoEscolhido: '',
        projetos: [],
        fields: [
          {key: 'tituloProjeto', label: 'Título', sortable: true},
          {key: 'curso.abreviacao', label: 'Curso', sortable: true},
          {key: 'autores', label: 'Autores', sortable: false},
          {key: 'orientadores', label: 'Orientador', sortable: true, formatter: value => value == null ? 'Sem Orientador' : value.nomeOrientador},
          {key: 'dataAvaliacao', label: 'Ano', sortable: true},
          {key: 'actions', label: 'Ações'}
        ],
        titulo: baseTitulo
      }
    },
    mounted(){
      axios.get(baseUrl + 'projetos/buscar/ranking')
          .then(response => {
          this.projetos = response.data.data
        })
        .catch()
      document.title = "BTA - Lista de Projetos",
      this.Redirecionar()
    },
    methods:{
      Redirecionar(){
        if(this.login != true){
          this.$router.push('/erro')
        }
      },
      modal(item){
        this.projetoEscolhido = item.tituloProjeto
        this.showModalEdit = true
      },
      Sucesso(){
        this.$toasted.show("Projeto Adicionado com Sucesso!!", { 
          type: "success", 
          icon: 'check',
          position: "top-right", 
          duration : 5000
        })
      },
      Fracasso(mensagem){
        this.$toasted.show(mensagem, { 
          type: "error", 
          icon: 'times',
          position: "top-right", 
          duration : 5000
        })
      }
    },
    filters: {
        formatarAlunos: alunos => {
            if(alunos[1] == null || alunos[1] == undefined)
              return alunos[0].nomeAutor
            if(alunos[2] == null || alunos[2] == undefined)
              return alunos[0].nomeAutor + ', ' + alunos[1].nomeAutor
            if(alunos[3] == null || alunos[3] == undefined)
              return alunos[0].nomeAutor + ', ' + alunos[1].nomeAutor + ', ' + alunos[2].nomeAutor
            if(alunos[4] == null || alunos[4] == undefined)
              return alunos[0].nomeAutor + ', ' + alunos[1].nomeAutor + ', ' + alunos[2].nomeAutor + ', ' + alunos[3].nomeAutor
            if(alunos[5] == null || alunos[5] == undefined)
              return alunos[0].nomeAutor + ', ' + alunos[1].nomeAutor + ', ' + alunos[2].nomeAutor + ', ' + alunos[3].nomeAutor + ', ' + alunos[4].nomeAutor
        },
        formatarAno: ano =>{
          return ano.substr(12, 4);
        }
    }
}
</script>

<style>
  #projetoList-content{
    grid-area: contentAdmin;
    background-color: #efefef;
    padding: 20px;
  }
</style>