<template>
  <div class="admin-page" v-if="true">
    <Header :title="titulo" :hideToggle="false" />
    <Menu />
    <div id="projetoAdd-content">
      <PageTitle icon="fa fa-home" main="Projeto" sub="Cadastro" />
      <b-form>
        <b-row>
          <b-col md="6" sm="12">
            <b-form-group label="Título do Projeto:" label-for="projeto-titulo">
              <b-form-input
                id="projeto-name"
                type="text"
                v-model="projeto.titulo"
                placeholder="Digite o Título do Projeto"
                required
              ></b-form-input>
            </b-form-group>
          </b-col>
          <b-col md="6" sm="12">
            <b-form-group label="Subtítulo do Projeto:" label-for="projeto-subtitulo">
              <b-form-input
                id="projeto-subtitulo"
                type="text"
                v-model="projeto.subTitulo"
                placeholder="Digite o Subtítulo do Projeto"
                required
              ></b-form-input>
            </b-form-group>
          </b-col>
        </b-row>
        <b-row>
          <b-col md="4" sm="12">
            <b-form-group label="Orientador:" label-for="projeto-orientador">
              <b-form-input
                id="input-orientador"
                list="listaDeOrientadores"
                v-model="nomeOrientadorSelecionado"
                aria-describedby="input-live-help input-live-feedback"
                placeholder="Digite o Nome do Orientador"
                trim
              ></b-form-input>
              <datalist id="listaDeOrientadores">
                <div v-for="item in optionOrientadores">
                  <option :value="item.text"></option>
                </div>
              </datalist>
            </b-form-group>
          </b-col>
          <b-col md="4" sm="12">
            <b-form-group label="Curso:" label-for="projeto-curso">
              <b-form-input
                id="input-curso"
                list="listaDeCursos"
                v-model="nomeCursoSelecionado"
                aria-describedby="input-live-help input-live-feedback"
                placeholder="Digite o Nome do Curso"
                trim
              ></b-form-input>
              <datalist id="listaDeCursos">
                <div v-for="item in optionsCurso">
                  <option :value="item.text"></option>
                </div>
              </datalist>
            </b-form-group>
          </b-col>
          <b-col md="4" sm="12">
            <b-form-group label="Data de Avaliação:" label-for="projeto-curso">
              <input id="date" type="date" class="form-control" v-model="projeto.dataAvalicao" />
            </b-form-group>
          </b-col>
        </b-row>
        Nome: {{nomeCursoSelecionado}} -- CursoId: {{this.projeto.curso}}
        <div>
          <b-row v-for="i in contAluno" :key="i">
            <b-col md="6" sm="12">
              <b-form-group :label="'Nome do Aluno ' + i + ':'" label-for="projeto-aluno-nome">
                <b-form-input
                  id="projeto-aluno-nome"
                  type="text"
                  v-model="projeto.aluno.nome[i-1]"
                  :placeholder="'Digite o Nome do Aluno ' + i"
                  required
                ></b-form-input>
              </b-form-group>
            </b-col>
            <b-col md="6" sm="12">
              <b-form-group :label="'RA do Aluno ' + i + ':'" label-for="projeto-aluno-ra">
                <b-form-input
                  id="projeto-aluno-ra"
                  type="text"
                  v-model="projeto.aluno.ra[i-1]"
                  :placeholder="'Digite o RA do Aluno ' + i"
                  required
                ></b-form-input>
              </b-form-group>
            </b-col>
          </b-row>
          <b-button @click="adicionarCont(1)" class="mb-3 mr-2">Adicionar Aluno</b-button>
          <b-button variant="danger" @click="removerCont(1)" class="mb-3">Remover Aluno</b-button>
        </div>
        <div>
          <b-row>
            <b-col md="3" sm="6" v-for="i in contPalavras" :key="i">
              <b-form-group :label="'Palavra-Chave ' + i + ':'" label-for="projeto-aluno">
                <b-form-input
                  id="projeto-palavra"
                  type="text"
                  v-model="projeto.palavra[i-1]"
                  :placeholder="'Digite a Palavra-Chave ' + i"
                  required
                ></b-form-input>
              </b-form-group>
            </b-col>
          </b-row>
          <b-button @click="adicionarCont(2)" class="mb-3 mr-2">Adicionar Palavra-Chave</b-button>
          <b-button variant="danger" @click="removerCont(2)" class="mb-3">Remover Palavra-Chave</b-button>
        </div>
        <b-row>
          <b-col md="12" sm="12">
            <b-form-group label="Resumo do Projeto" label-for="projeto-aluno">
              <b-form-textarea
                id="projeto-resumo"
                v-model="projeto.resumo"
                placeholder="Resumo do Projeto..."
                rows="3"
                max-rows="6"
              ></b-form-textarea>
            </b-form-group>
          </b-col>
        </b-row>
        <b-row>
          <b-col md="12">
            <b-form-group label="Arquivo do Projeto" label-for="projeto-aluno">
              <b-form-file
                accept=".pdf"
                v-model="projeto.file"
                :state="Boolean(projeto.file)"
                placeholder="Escolha um arquivo PDF ou coloque-o aqui"
                drop-placeholder="Pesquisar"
              ></b-form-file>
              <!-- <input type="file" id="file" ref="file" v-on:change="handleFileUpload()"/> -->
            </b-form-group>
          </b-col>
        </b-row>
        <b-button variant="primary" @click="save">Salvar</b-button>
        <b-button class="ml-2" @click="reset">Cancelar</b-button>
      </b-form>
    </div>
    <Footer />
  </div>
</template>

<script>
import { baseUrl, baseTitulo } from "../../../config/global";
import axios from "axios";
import PageTitle from "../templates/PageTitle";
import Header from "../templates/Header";
import Menu from "../templates/Menu";
import Footer from "../templates/Footer";

export default {
  name: "UsuarioList",
  components: { PageTitle, Header, Menu, Footer },
  computed: {
    CodigoState() {
      return this.projeto.orientador.length == 10 ? true : false;
    }
  },
  data: function() {
    return {
      lista: ["Maçã", "Pera"],
      response: "",
      projeto: {
        titulo: "",
        subTitulo: "",
        aluno: {
          nome: [],
          ra: []
        },
        palavra: [],
        curso: '',
        orientador: '1237816283',
        resumo: "",
        file: null,
        dataAvaliacao: "2019-11-11"
      },
      nomeCursoSelecionado: '',       //id do Curso Selecionado
      optionsCurso: [],               //id e nome dos cursos
      jsonCursos: [],                 //json dos cursos
      nomeOrientadorSelecionado: '',  //id do Orientador Selecionado
      optionOrientadores: [],         //id e nome dos orientadores
      jsonOrientadores: [],           //json dos orientadores
      contAluno: 1,
      contPalavras: 1,
      titulo: baseTitulo
    };
  },
  methods: {
    save() {
      // alert('1')
      //Curso
      const cursoSelecionado = this.nomeCursoSelecionado
      let cursoId
      const cursoIdFunction = this.optionsCurso.reduce((y, x) => {
        if(x.text == cursoSelecionado){
          cursoId = x.value
        }
      }, 0)
      this.projeto.curso = cursoId
      if(!cursoId){
        this.Fracasso("Curso não encontrado")
        return;
      }
      
      // alert('2')
      // //Orientador
      // const orientadorSelecionado = this.nomeOrientadorSelecionado
      // let orientadorId
      // const orientadorIdFunction = this.optionOrientadores.reduce((y, x) => {
      //   if(x.text == orientadorSelecionado){
      //     orientadorId = x.value
      //   }
      // }, 0)
      // this.projeto.orientador = orientadorId
      // if(!orientadorId)
      //   this.Fracasso("Orientador não encontrado")
      //   return;
      
      alert("Chegou aqui 0");
      let d = new FormData();
      d.append("titulo", this.projeto.titulo);
      d.append("raOrientador", this.projeto.orientador);
      d.append("descricao", this.projeto.resumo);
      d.append("dataAvaliacao", this.projeto.dataAvaliacao);
      d.append("curso", this.projeto.curso);
      d.append("subTitulo", this.projeto.subTitulo);
      d.append('file', this.projeto.file);
      for(let i = 0; i < this.projeto.aluno.nome.length; i++){
        if(i == 0){
          d.append("autor", this.projeto.aluno.nome[i]);
          d.append('ra_autor', this.projeto.aluno.ra[i]);
          continue;
        }
        d.append("autor_" + i, this.projeto.aluno.nome[i]);
        d.append('ra_autor_' + i, this.projeto.aluno.ra[i]);
      }
      for(let i = 0; i < this.projeto.palavra.length; i++){
        alert(this.projeto.palavra[i])
        if(i == 0){
          d.append("palavra_chave", this.projeto.palavra[i]);
          continue;
        }
        d.append("palavra_chave_" + i, this.projeto.palavra[i]);
      }
      axios
        .post(baseUrl + "projetos/cadastrar", d,
        {
          headers: {
              'Content-Type': 'multipart/form-data'
          }
        })
        .then(response => {
          this.Sucesso();
          this.response = response;
          // if(false){

          // }
        })
        .catch(c => {
          this.Fracasso(c);
          return;
        });
    },
    handleFileUpload(){
      this.file = this.$refs.file.files[0];
    },
    GetCursos() {
      axios
        .get(baseUrl + "cursos/buscar")
        .then(response => {
          this.jsonCursos = response.data.data;
          let array = [];
          this.optionsCurso = this.jsonCursos.reduce(function(
            acumulador,
            valorAtual
          ) {
            array.push({
              value: valorAtual.codCurso,
              text: valorAtual.descricaoCurso
            });
            return array;
          },
          []);
        })
        .catch();
    },
    GetOrientadores() {
      axios
        .get(baseUrl + "orientadores/buscar")
        .then(response => {
          this.jsonOrientadores = response.data.data;
          let array = [];
          this.optionOrientadores = this.jsonOrientadores.reduce(function(acumulador, valorAtual) {
            array.push({
              value: valorAtual.raOrientador,
              text: valorAtual.nomeOrientador
            });
            return array;
          },
          []);
        })
        .catch();
    },
    removerCont(x) {
      if (this.contAluno > 1 && x == 1) return this.contAluno--;
      if (this.contPalavras > 1 && x == 2) return this.contPalavras--;
    },
    adicionarCont(x) {
      if (this.contAluno != 5 && x == 1) return this.contAluno++;
      if (this.contPalavras != 5 && x == 2) return this.contPalavras++;
    },
    reset() {
      this.projeto = {};
    },
    Redirecionar() {
      if (this.login != true) {
        //this.$router.push('/erro')
      }
    },
    Sucesso() {
      this.$toasted.show("Projeto Adicionado com Sucesso!!", {
        type: "success",
        icon: "check",
        position: "top-right",
        duration: 5000
      });
    },
    Fracasso(mensagem) {
      this.$toasted.show(mensagem, {
        type: "error",
        icon: "times",
        position: "top-right",
        duration: 5000
      });
    }
  },
  mounted() {
    (document.title = "BTA - Adicionar Projeto"),
      // this.Redirecionar()
      this.GetCursos();
      this.GetOrientadores()
  }
};
</script>

<style>
#projetoAdd-content {
  grid-area: contentAdmin;
  background-color: #efefef;
  padding: 20px;
}

.custom-file-input:lang(en) ~ .custom-file-label::after {
  content: "Buscar";
}
</style>