<template>
  <div class="admin-page" v-if="login">
    <Header :title="titulo" :hideToggle="false"/>
    <Menu />
    <div id="usuarioAdd-content">
      <PageTitle icon="fa fa-home" main="Usuário" sub="Cadastrar"/>
      <b-form>
        <input id="user-id" type="hidden" v-model="user.id">
        <b-row>
          <b-col md="4" sm="12">
              <b-form-group label="Apelido:" label-for="user-username">
                  <b-form-input id="user-username" type="text" v-model="user.apelido" placeholder="Digite o Apelido do Usuário" required>
                  </b-form-input>
              </b-form-group>
          </b-col>
          <b-col md="4" sm="12">
              <b-form-group label="Nome:" label-for="user-name">
                  <b-form-input id="user-name" type="text" v-model="user.nome" placeholder="Digite o Nome do Usuário" required>
                  </b-form-input>
              </b-form-group>
          </b-col>
          <b-col md="4" sm="12">
              <b-form-group label="E-mail:" label-for="user-email">
                  <b-form-input id="user-email" type="text" v-model="user.email" placeholder="Digite o E-mail do Usuário" required>
                  </b-form-input>
              </b-form-group>
          </b-col>
        </b-row>
        
        <b-row>
          <b-col md="12" sm="12">
            <b-form-group label="Tipo de Usuário">
              <b-form-radio-group
                v-model="user.nivel"
                :options="options"
              ></b-form-radio-group>
            </b-form-group>
          </b-col>
        </b-row>
        <b-row>
          <b-col md="6" sm="12">
              <b-form-group label="Senha:" label-for="user-password">
                  <b-form-input id="user-password" type="password" v-model="user.password" placeholder="Digite a Senha do Usuário" required>
                  </b-form-input>
              </b-form-group>
          </b-col>
          <b-col md="6" sm="12">
              <b-form-group label="Conrimação de Senha:" label-for="user-confirm-password">
                  <b-form-input id="user-confirm-password" type="password" v-model="user.confirmPassword" placeholder="Confirme a Senha do Usuário" required>
                  </b-form-input>
              </b-form-group>
          </b-col>
        </b-row>
        <b-button variant="primary" @click='save'>
          Salvar
        </b-button>
        <b-button class="ml-2" @click='reset'>
          Cancelar
        </b-button>
      </b-form>
    </div>
    <Footer />
  </div>
</template>

<script>
import { baseUrl, baseTitulo } from '../../../config/global'
import { mapState } from 'vuex'
import axios from 'axios'
import PageTitle from '../templates/PageTitle'
import Header from '../templates/Header'
import Menu from '../templates/Menu'
import Footer from '../templates/Footer'

export default {
    name: 'UsuarioList',
    components: { PageTitle, Header, Menu, Footer },
    props: ['idUsuario'],
    computed: mapState(['login']),
    data: function(){
      return{
        options: [
          { text: 'Secretaria', value: '1' },
          { text: 'Administração', value: '3' }
        ],
        user:{
          apelido: '',
          nome: '',
          email: '',
          password: '',
          confirmPassword: '',
          nivel: ''
        },
        titulo: baseTitulo,
        id: ''
      }
    },
    methods:{
      reset(){
        this.user = {}
      },
      save(){
        // alert(this.user.password)
        // alert(this.user.confirmPassword)
        // if(this.user.password != this.user.confirmPassword || this.user.password != ''){
        //   this.Fracasso('As senhas não são iguais')
        //   return
        // }
        let d = new FormData()
        d.append('username', this.user.apelido)
        d.append('nome', this.user.nome)
        d.append('email', this.user.email)
        d.append('tipoUsuario', this.user.nivel)
        d.append('password', this.user.password)
        axios.post(baseUrl + 'usuarios/cadastrar', d)
          .then(() => {
            this.Sucesso()
            // if(false){
              
            // }
            this.$router.push('/admin/usuario')
          })
          .catch(c => {
            this.Fracasso(c)
            return
          })
      },
      Redirecionar(){
        if(this.login != true){
          this.$router.push('/erro')
        }
      },
      Sucesso(){
        this.$toasted.show("Usuário Adicionado com Sucesso!!", { 
          type: "success", 
          icon: 'check',
          position: "top-right", 
          duration : 5000
        })
      },
      Fracasso(mensagem){
        this.$toasted.show(mensagem, { 
          type: "error", 
          icon: 'times',
          position: "top-right", 
          duration : 5000
        })
      }
    },
    mounted(){
      document.title = "BTA - Adicionar Usuário",
      this.Redirecionar()
    }
}
</script>

<style>
  #usuarioAdd-content{
    grid-area: contentAdmin;
    background-color: #efefef;
    padding: 20px;
  }
</style>