<template>
    <div class="page">
        <!-- HEADER -->
        <Header />
        
        <main class="main">
            <!-- CARROUSEL -->
            <div id="carrousel">
            <b-carousel
            id="carousel-1"
            :interval="4000"
            controls
            indicators
            background="#ababab"
            img-width="1024"
            img-height="400"
            style="text-shadow: 1px 1px 2px #333;"
            >
                <!-- Text slides with image -->
                <b-carousel-slide
                caption="Primeiro Título"
                text="Primeiro SubTítulo"
                img-src="https://picsum.photos/id/1068/1024/400"
                ></b-carousel-slide>
                <!-- Text slides with image -->
                <b-carousel-slide
                caption="Segundo Título"
                text="Segundo SubTítulo"
                img-src="https://picsum.photos/id/1000/1024/400"
                ></b-carousel-slide>
                <!-- Text slides with image -->
                <b-carousel-slide
                caption="Terceiro Título"
                text="Terceiro SubTítulo"
                img-src="https://picsum.photos/id/1050/1024/400"
                ></b-carousel-slide>
            </b-carousel>
            </div>


            <!-- SOBRE -->
            <article class="container">
                <h3>Sobre</h3>
                <p class="text-center">Lorem ipsum dolor sit amet, consectetur adipiscing elit. Ut varius dui eget turpis finibus luctus. Curabitur ut ullamcorper massa, in viverra dui. Ut placerat, nisi at consectetur ullamcorper, lorem ipsum gravida mi, sit amet feugiat lacus nisi in lacus. Nulla faucibus nunc lorem, non egestas dui finibus sed. Morbi maximus suscipit nunc, sed aliquet justo sollicitudin tristique.</p>
            </article>

            <!-- BUSCA -->
            <article class="container w-75">
                <div>
                    <h3>Busca</h3>
                    <div class="active-pink-4 mb-4">
                        <input class="form-control" type="text" placeholder="Pesquisar" v-model="valorBusca">
                    </div>
                    <div id="grupoBotaoBusca">
                        <router-link :to="'/busca?busca=' + this.valorBusca"  class="botoesBusca">
                            <b-button variant="outline-danger" >Buscar</b-button>
                        </router-link>
                    </div>
                </div>
            </article>

            <!-- RANKING -->
            <article class="container">
                <h3>Ranking</h3>
                    <b-table 
                    class="table-rank"
                    striped hover responsive
                    :items="projetos" 
                    :fields="fields"
                    :sort-by.sync="sortBy"
                    :sort-desc.sync="sortDesc"
                    :per-page="perPage"
                    :current-page="currentPage"
                >
                    <template slot="action" slot-scope="trabalho">
                        <router-link :to="'/projeto?id=' + trabalho.item.codProjeto">
                            <a>
                                <button class="outline black">
                                    <i class="fa fa-search"></i>
                                </button>
                            </a>
                        </router-link>
                    </template>
                    <template slot="autores" slot-scope="aluno">
                        {{ aluno.item.autores|formatarAlunos }}
                    </template>
                    <template slot="dataAvaliacao" slot-scope="dataAvaliacao">
                        {{ dataAvaliacao.item.dataAvaliacao|formatarAno }}
                    </template>
                    <template slot="download" slot-scope="downloadItem">
                        <a :href="url + 'projetos/download_file/' + downloadItem.item.nomeArquivo" download="">
                            <button class="outline black">
                                <i class="fa fa-download"></i>
                            </button>
                        </a>
                    </template>
                </b-table>
                <div class="botaoCentro mt-3">
                    <router-link to="/ranking">
                        <b-button variant="outline-danger">Ranking Completo</b-button>
                    </router-link>
                </div>
            </article>
        </main>
        <Footer />
    </div>
</template>

<script>
import { baseUrl } from '../../../config/global'
import axios from 'axios'
import Header from '../templates/Header'
import Footer from '../templates/Footer'

export default {
    name: 'homePage',
    components: { Header, Footer },
    data: function() {
        return {
            valorBusca: '',
            baseClass: 'v-icon',
            sortBy: 'likes',
            sortDesc: true,
            perPage: 5,
            currentPage: 1,
            projetos: [],
            url: baseUrl,
            fields: [
                {key: 'action', label: 'Visualizar', sortable: false},
                {key: 'tituloProjeto', label: 'Título', sortable: true},
                {key: 'curso.abreviacao', label: 'Curso', sortable: true},
                {key: 'autores', label: 'Autores', sortable: false},
                {key: 'orientadores', label: 'Orientador', sortable: true, formatter: value => value == null ? 'Sem Orientador' : value.nomeOrientador},
                {key: 'dataAvaliacao', label: 'Ano', sortable: true},
                {key: 'likes', label: 'Likes', sortable: true},
                {key: 'download', label: 'Download'}
            ]
        }
    },
    mounted(){
        axios
        .get(baseUrl + 'projetos/buscar/ranking')
            .then(response => (this.projetos = response.data.data))
        document.title = "BTA - Index"
    },
    filters: {
        formatarAlunos: alunos => {
            if(alunos[1] == null || alunos[1] == undefined)
              return alunos[0].nomeAutor
            if(alunos[2] == null || alunos[2] == undefined)
              return alunos[0].nomeAutor + ', ' + alunos[1].nomeAutor
            if(alunos[3] == null || alunos[3] == undefined)
              return alunos[0].nomeAutor + ', ' + alunos[1].nomeAutor + ', ' + alunos[2].nomeAutor
            if(alunos[4] == null || alunos[4] == undefined)
              return alunos[0].nomeAutor + ', ' + alunos[1].nomeAutor + ', ' + alunos[2].nomeAutor + ', ' + alunos[3].nomeAutor
            if(alunos[5] == null || alunos[5] == undefined)
              return alunos[0].nomeAutor + ', ' + alunos[1].nomeAutor + ', ' + alunos[2].nomeAutor + ', ' + alunos[3].nomeAutor + ', ' + alunos[4].nomeAutor
        },
        formatarAno: ano =>{
          return ano.substr(12, 4);
        }
    }
}

</script>

<style>
.itemMenu{
    color: black;
}

.itemMenu:hover{
    text-decoration: none;
}

article{
    margin: 10px 0;
}

article h3{
    text-align: center;
    padding: 10px;
}

.itemFooter{
    padding: 10px 0px;
}

.table th, .table td {
    padding: 0.75rem;
    vertical-align: center;
    border-top: 1px solid #dee2e6;
}
</style>