//Variáveis Globais

import Vue from 'vue'

export const baseUrl = "/"
export const baseTitulo = "Biblioteca de Trabalhos Científicos"

export function showError(e){
    if(typeof e === String){
        Vue.toasted.global.defaultError({ msg : e })
    } 
    else{
        Vue.toasted.global.defaultError()
    }
}
