<template>
    <div class="user-dropdown">
        <div class="user-button">
            <span class="d-none d-sm-block">{{user.name}}</span>
            <div class="user-dropdown-img">
                <Gravatar :email='user.email' alt="User" />
            </div>
            <i class="fa fa-angle-down"></i>
        </div>
        <div class="user-dropdown-content">
            <a @click="Logout"><i class="fa fa-sign-out">Sair</i></a>
        </div>
    </div>
</template>

<script>
import { baseUrl } from '../../../config/global'
import axios from 'axios'
import { mapState } from 'vuex'
import Gravatar from 'vue-gravatar'

export default {
    name: 'UserDropdown',
    components: { Gravatar },
    computed: mapState(['user', 'login']),
    data(){
        return{
            nome: '',
            email: ''
        }
    },
    methods:{
        Logout(){
            axios
            .get(baseUrl + 'usuarios/logout')
                .then(response => (this.projetos = response.data.data))
            this.$router.push('/')
            this.MensagemLogout()
        },
        MensagemLogout(){
            this.$toasted.show("Logout feito com sucesso", { 
            type: "toasted-primary", 
            icon: 'lock',
            position: "top-right", 
            duration : 5000
            })
        },
        GetName(){
            axios
            .get(baseUrl + 'usuarios/logged')
                .then(response => (this.projetos = response.data.data))
        }
    },
    mounted() {
        this.GetName()
    }
}
</script>

<style>
.user-dropdown{
    position: relative;
    height: 100%;
}

.user-button{
    display: flex;
    align-items: center;
    color: white;
    font-weight: 100;
    height: 100%;
    padding: 0px 20px;
}

.user-button:hover{
    background-color: rgba(0, 0, 0, 0.2);
}

.user-dropdown-img{
    margin: 0px 10px;
}

.user-dropdown-img > img{
    max-height: 37px;
    border-radius: 5px;
}

.user-dropdown-content{
    position: absolute;
    right: 0px;
    background-color: #f9f9f9;
    min-width: 170px;
    box-shadow: 0px 8px 16px 0px rgba(0, 0, 0, 0.2);
    padding: 10px;
    z-index: 1;

    display: flex;
    flex-direction: column;
    flex-wrap: wrap;

    visibility: hidden;
    opacity: 0;
    transition: visibility 0s, opacity 0.5s linear;
}

.user-dropdown:hover .user-dropdown-content{
    visibility: visible;
    opacity: 1;
}

.user-dropdown-content a{
    text-decoration: none;
    color: black;
    padding: 10px;
}

.user-dropdown-content a:hover{
    background-color: #ededed;
    text-decoration: none;
    color: black;
}
</style>