<template>
  <div class="admin-page" v-if="login">
    <Header :title="titulo" :hideToggle="false"/>
    <Menu />
    <div id="orientadorAdd-content">
      <PageTitle icon="fa fa-home" main="Orientador" sub="Editar"/>
      {{this.$route.query.id}}
      <b-form>
        <b-row>
          <b-col md="6" sm="12">
              <b-form-group label="Nome:" label-for="orientador-name">
                  <b-form-input id="orientador-name" type="text" v-model="orientador.nome" placeholder="Digite o Nome do Orientador" required>
                  </b-form-input>
              </b-form-group>
          </b-col>
          <b-col md="6" sm="12">
              <b-form-group label="Código do Orientador:" label-for="orientador-codigo">
                  <b-form-input id="orientador-email" type="text" v-model="orientador.codigo" placeholder="Digite o Código de Matricula do Orientador" required>
                  </b-form-input>
              </b-form-group>
          </b-col>
        </b-row>
        <b-button variant="primary" @click='save'>
          Salvar
        </b-button>
        <b-button class="ml-2" @click='reset'>
          Cancelar
        </b-button>
      </b-form>
    </div>
    <Footer />
  </div>
</template>

<script>
import { baseUrl, baseTitulo } from '../../../config/global'
import { mapState } from 'vuex'
import axios from 'axios'
import PageTitle from '../templates/PageTitle'
import Header from '../templates/Header'
import Menu from '../templates/Menu'
import Footer from '../templates/Footer'

export default {
    name: 'UsuarioList',
    components: { PageTitle, Header, Menu, Footer },
    computed: mapState(['login']),
    data: function(){
      return{
        orientador:{
          nome: '',
          codigo: ''
        },
        titulo: baseTitulo
      }
    },
    methods:{
      reset(){
        this.orientador = {}
      },
      save(){
        let d = new FormData()
        d.append('raOrientador', this.orientador.codigo)
        d.append('nomeOrientador', this.orientador.nome)
        axios.post(baseUrl + 'orientadores/cadastrar', d)
          .then((response) => {
            if(response.data.status == 'negado'){
              this.Fracasso(response.data)
              return
            }
            this.Sucesso()
            this.$router.push('/admin/orientador')
          })
          .catch()
      },
      Redirecionar(){
        if(this.login != true){
          this.$router.push('/erro')
        }
      },
      Sucesso(){
        this.$toasted.show("Orientador Adicionado com Sucesso!!", { 
          type: "success", 
          icon: 'check',
          position: "top-right", 
          duration : 5000
        })
      },
      Fracasso(mensagem){
        this.$toasted.show(mensagem, { 
          type: "error", 
          icon: 'times',
          position: "top-right", 
          duration : 5000
        })
      },
      CarregarOrientador(){
        axios.get(baseUrl + 'orientador/get/' + this.$route.query.id)
          .then(response => {
            if(response.data.cod_s == 0){
              this.Fracasso(response.data.status)
              return
            }
            this.user.nome = response.data.data.nomeUsuario
            this.user.nivel = response.data.data.tipoUsuario
          })
      }
    },
    mounted(){
      this.CarregarOrientador()
      document.title = "BTA - Editar Orientador",
      this.Redirecionar()
    }
}
</script>

<style>
  #orientadorAdd-content{
    grid-area: contentAdmin;
    background-color: #efefef;
    padding: 20px;
  }
</style>